/**
 * lyria_score_b64.js — Seamless 21.42s (10-bar) equal-power crossfade-looped Lyria 3.5
 * California coastal indie-funk / acoustic-electronic cruiser score (112.0 BPM, 128kbps stereo MP3, Base64-inlined for Origin:null).
 * Stem source: audio_stems/lyria_v7_california_cruiser.mp3 (zero vocals, permanently locked 1.000x playbackRate).
 */
export const LYRIA_SCORE_MIME = "audio/mpeg";
export const LYRIA_SCORE_BPM = 112.0;
export const LYRIA_SCORE_BASE64 = "";

export function decodeLyriaScoreArrayBuffer() {
  if (typeof atob === "function") {
    const bin = atob(LYRIA_SCORE_BASE64);
    const len = bin.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
    return bytes.buffer;
  }
  const buf = Buffer.from(LYRIA_SCORE_BASE64, "base64");
  return buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength);
}
